namespace ghidra.app.plugin.core.compositeeditor;

using docking;
using ghidra.util.exception;

public class AddBitFieldAction : CompositeEditorTableAction {

	public static string ACTION_NAME = "Add Bitfield";
	private static string GROUP_NAME = BITFIELD_ACTION_GROUP;
	private static string DESCRIPTION =
		"Add a bitfield at the position of a selected component";
	private static string[] POPUP_PATH = new string[] { ACTION_NAME };

	public AddBitFieldAction(CompositeEditorProvider<object,object> provider) : base(provider, ACTION_NAME, GROUP_NAME, POPUP_PATH, null, null)
    {
		setDescription(DESCRIPTION);
		if (!(model is CompEditorModel)) {
			throw new AssertException("unsupported use");
		}
	}

	/* @Override */
	public void actionPerformed(ActionContext context) {
		StructureEditorProvider structProvider = (StructureEditorProvider) provider;
		structProvider.showAddBitFieldEditor();
	}

	/* @Override */
	public bool isEnabledForContext(ActionContext context) {
		if (hasIncompleteFieldEntry()) {
			return false;
		}
		bool enabled = true;
		CompEditorModel<object> editorModel = (CompEditorModel<object>) model;
		// Unions do not support non-packed manipulation of bitfields
		if (!(provider is StructureEditorProvider) ||
			editorModel.isPackingEnabled() || editorModel.getNumSelectedRows() != 1) {
			enabled = false;
		}
		return enabled;
	}

}
